<#
  Sovereign Browser - launcher + website list (Windows)

  Runs either way:
    - as a script:      right-click -> Run with PowerShell
    - as an .exe:       compiled by build-exe.ps1

  If the Google Cloud CLI isn't installed, the app installs it for you and
  tracks the install on a progress bar. If you aren't signed in, it opens the
  sign-in flow for you. The website list is yours to edit.
#>

Add-Type -AssemblyName System.Windows.Forms
Add-Type -AssemblyName System.Drawing

# ------------------------------------------------------------- remote bits --
# Deliberately free of > | & " % so nothing gets mangled passing through
# gcloud.cmd on Windows. $B64 is substituted at call time.
#
# Both of these finish with `bash setup.sh` rather than `docker restart`. A
# restart keeps the container's filesystem, so a stale X lock left behind by the
# previous run makes Xvfb refuse to start ("Server is already active for display
# 1") and the session comes back with a blank screen. setup.sh removes and
# re-creates the container, and it also re-generates policies.json and the hub
# page from the list that was just written, so the page and the policy can never
# drift apart.
#
# If the Cloud Shell side does not exist at all (brand-new session, or Cloud
# Shell recycled the VM and wiped $HOME), there is no ~/cybershield/setup.sh to
# run. Start-Remote checks for it before running either command, uploads the
# installer this app carries ($SetupScriptB64 below, generated from
# cloudshell-setup.sh), verifies it byte for byte, runs it - and only then runs
# the command. So Launch alone is enough, even on a fresh account.
#
# Every marker is echoed twice with a pause between the copies: the ssh tunnel
# can drop the last line of output while it closes, and when that line is the
# marker, a run that actually worked looks like it failed.
$RemotePushStart = 'python3 $HOME/cybershield/write_policy.py $B64; bash $HOME/cybershield/setup.sh > $HOME/cybershield/launch.log 2>&1; for i in $(seq 1 45); do s=$(docker inspect -f {{.State.Health.Status}} cybershield); test $s = healthy && break; sleep 2; done; echo CYBERSHIELD_HOST=$WEB_HOST; sleep 1; echo CYBERSHIELD_HOST=$WEB_HOST'
$RemotePushReset = 'python3 $HOME/cybershield/write_policy.py $B64; bash $HOME/cybershield/setup.sh > $HOME/cybershield/launch.log 2>&1; echo CYBERSHIELD_RESET=ok; sleep 1; echo CYBERSHIELD_RESET=ok'

# Turns the locked session off without tearing anything down: stops the
# container, so the screen inside the session goes dead until the next Launch
# or Reset brings it back. There is nothing to set up first, so this command
# skips the installer check - stopping something that is not there is not an
# error, and the state probe would only cost time.
$RemoteSessionOff = 'docker stop cybershield >/dev/null 2>&1; sleep 1; docker inspect -f {{.State.Status}} cybershield 2>/dev/null; echo CYBERSHIELD_OFF=ok; sleep 1; echo CYBERSHIELD_OFF=ok'

$CloudSdkInstaller = 'https://dl.google.com/dl/cloudsdk/channels/rapid/GoogleCloudSDKInstaller.exe'

# cloudshell-setup.sh, the Cloud Shell side of the app, carried inside this
# build in base64 so a fresh Cloud Shell needs nothing pasted by hand.
# Start-Remote uploads and runs it when ~/cybershield/setup.sh is missing.
# Regenerate after editing cloudshell-setup.sh - from PowerShell, in this folder:
#
#   [Convert]::ToBase64String([IO.File]::ReadAllBytes("$PWD\cloudshell-setup.sh"))
#
# and paste the single line it prints over the placeholder below. The file's LF
# line endings are part of the value: the bytes are uploaded as-is and run by
# bash, and CRLF would break it there ("$'\r': command not found").
$SetupScriptB64 = ''

$script:ps          = $null
$script:handle      = $null
$script:marker      = ''
$script:lastUrl     = ''
$script:Gcloud      = $null
$script:SetupAction = 'install'
$script:Account     = ''

# Progress is published from the worker runspace and read here on the UI
# thread, so it has to be a shared, thread-safe object.
$script:Progress = [hashtable]::Synchronized(@{
    phase   = ''
    detail  = ''
    percent = -1
    read    = 0
    total   = 0
})

$script:JobStart   = Get-Date
$script:LastSample = Get-Date
$script:LastRead   = 0
$script:SpeedBps   = 0
$script:MarqueePos = -140

# ------------------------------------------------------------ gcloud lookup -
function Find-Gcloud {
    # Prefer gcloud.cmd / gcloud.exe, and deliberately NEVER gcloud.ps1.
    # The SDK installer puts its bin folder on PATH, and that folder ships
    # gcloud, gcloud.cmd AND gcloud.ps1 - PowerShell's Get-Command prefers the
    # .ps1. Handing a .ps1 to Start-Process goes to the file association, which
    # on a machine with no .ps1 association is a "How do you want to open this
    # file?" dialog rather than a gcloud run.
    foreach ($dir in @($env:Path -split ';')) {
        if (-not $dir) { continue }
        $d = $dir.Trim().Trim('"')
        if (-not $d -or $d.Contains('%')) { continue }   # skip unexpanded %VARS%
        foreach ($n in @('gcloud.cmd', 'gcloud.exe')) {
            try {
                $p = Join-Path $d $n
                if (Test-Path $p) { return $p }
            } catch { }
        }
    }

    $roots = @($env:ProgramFiles, ${env:ProgramFiles(x86)}, $env:LOCALAPPDATA)
    foreach ($r in $roots) {
        if (-not $r) { continue }
        foreach ($rel in @('Google\Cloud SDK\google-cloud-sdk\bin\gcloud.cmd',
                           'Google\CloudSDK\google-cloud-sdk\bin\gcloud.cmd')) {
            $p = Join-Path $r $rel
            if (Test-Path $p) { return $p }
        }
    }

    # last resort: whatever the shell resolves, as long as it is not a .ps1
    $cmd = @(Get-Command gcloud -ErrorAction SilentlyContinue) |
           Where-Object { $_.Source -and $_.Source -notlike '*.ps1' } |
           Select-Object -First 1
    if ($cmd) { return $cmd.Source }
    return $null
}

function Refresh-Path {
    try {
        $m = [Environment]::GetEnvironmentVariable('Path', 'Machine')
        $u = [Environment]::GetEnvironmentVariable('Path', 'User')
        if ($m -or $u) { $env:Path = "$m;$u" }
    } catch { }
}

# Open the session in a chromeless app window when Edge or Chrome is available.
#
# The outer window is only a viewer for the Cloud Shell machine. Its back
# button, reload and address bar drive THIS PC, not the locked browser inside -
# and typing in them takes the person out of the protected session entirely.
# An app window has no address bar, no tabs and no back button, so the only
# browser controls on screen are the ones inside the session, which are the
# ones the policy governs. Falls back to the default browser if neither is here.
function Open-Session([string]$url) {
    if (-not $url) { return }
    $candidates = @()
    if (${env:ProgramFiles(x86)}) { $candidates += (Join-Path ${env:ProgramFiles(x86)} 'Microsoft\Edge\Application\msedge.exe') }
    if ($env:ProgramFiles)        { $candidates += (Join-Path $env:ProgramFiles 'Microsoft\Edge\Application\msedge.exe') }
    if ($env:ProgramFiles)        { $candidates += (Join-Path $env:ProgramFiles 'Google\Chrome\Application\chrome.exe') }
    if (${env:ProgramFiles(x86)}) { $candidates += (Join-Path ${env:ProgramFiles(x86)} 'Google\Chrome\Application\chrome.exe') }

    foreach ($exe in $candidates) {
        if (-not (Test-Path $exe)) { continue }
        try {
            Start-Process -FilePath $exe -ArgumentList ('--app=' + $url)
            return
        } catch { }
    }
    Start-Process $url
}

# winget downloads the package into %TEMP%\WinGet before installing it. Watching
# that folder gives a real "bytes downloaded" number even though winget itself
# keeps its own progress bar to itself.
function Get-WingetBytes {
    $t = Join-Path $env:TEMP 'WinGet'
    if (-not (Test-Path $t)) { return 0 }
    try {
        $sum = (Get-ChildItem $t -Recurse -File -ErrorAction SilentlyContinue |
                Measure-Object -Property Length -Sum).Sum
        if ($sum) { return [int64]$sum }
    } catch { }
    return 0
}

# ------------------------------------------------------ local config file ---
$base = $PSScriptRoot
if (-not $base) {
    $exe = $null
    try { $exe = [Diagnostics.Process]::GetCurrentProcess().MainModule.FileName } catch { }
    if ($exe -and (Split-Path -Leaf $exe) -notmatch '^powershell(_ise)?\.exe$') {
        $base = Split-Path -Parent $exe
    }
}
if (-not $base) { $base = $env:USERPROFILE }
$script:CfgPath = Join-Path $base 'cybershield-sites.json'
$script:LogPath = Join-Path $base 'cybershield.log'

# A plain-text record of every action, next to the .exe, so a demo failure can be
# explained afterwards instead of guessed at. Written from both the UI thread and
# the worker runspace, hence the lock; logging must never be able to crash the
# app, so every failure here is swallowed on purpose.
$script:LogLock = New-Object object

function Write-Log {
    param([string]$Message, [string]$Level = 'INFO')
    try {
        [Threading.Monitor]::Enter($script:LogLock)
        try {
            $line = '{0}  {1,-5}  {2}' -f (Get-Date).ToString('yyyy-MM-dd HH:mm:ss'), $Level, $Message
            Add-Content -LiteralPath $script:LogPath -Value $line -Encoding UTF8
        }
        finally { [Threading.Monitor]::Exit($script:LogLock) }
    } catch { }
}

function Normalize-Site([string]$s) {
    $s = $s.Trim().ToLower()
    $s = $s -replace '^[a-z]+://', ''   # strip https://
    $s = $s -replace '/.*$', ''         # strip path
    $s = $s -replace '^www\.', ''       # wildcard covers www anyway
    $s = $s.Trim('.')
    return $s
}

# ---------------------------------------------------------------- splash -----
# The logo is embedded as base64 rather than shipped beside the .exe, so
# the .exe stays one self-contained file: copy it anywhere and the splash
# still works. The white background of the source image has been cut out (flood
# filled from the edges, so the white *inside* the shield and the lock survives),
# which is why the logo can sit straight on the window colour with no white box.
$script:LogoB64 = ''

# A borderless window in the same colour as the app that fades the logo in and
# holds it. It is deliberately NOT closed here: the caller crossfades it away
# once the main window is up, so the desktop never flashes through between the
# two. Opacity is stepped by hand with DoEvents in between, because no message
# loop is running yet at this point - without DoEvents the window never repaints
# and the fade would land as a single jump.
function Show-Splash {
    param([int]$Size = 420, [int]$HoldMs = 900)

    try {
        $bytes  = [Convert]::FromBase64String($script:LogoB64)
        $script:SplashStream = New-Object IO.MemoryStream -ArgumentList (,$bytes)
        $script:SplashImg    = [Drawing.Image]::FromStream($script:SplashStream)

        $splash                 = New-Object Windows.Forms.Form
        $splash.FormBorderStyle = 'None'
        $splash.StartPosition   = 'CenterScreen'
        $splash.ShowInTaskbar   = $false
        $splash.TopMost         = $true
        $splash.BackColor       = [Drawing.Color]::FromArgb(11, 16, 32)
        $splash.ClientSize      = New-Object Drawing.Size -ArgumentList ($Size + 40), ($Size + 40)
        $splash.Opacity         = 0.0

        $pic           = New-Object Windows.Forms.PictureBox
        $pic.Image     = $script:SplashImg
        $pic.SizeMode  = 'Zoom'
        $pic.BackColor = [Drawing.Color]::FromArgb(11, 16, 32)
        $pic.Bounds    = New-Object Drawing.Rectangle -ArgumentList 20, 20, $Size, $Size
        $splash.Controls.Add($pic)

        $splash.Show()
        $splash.Refresh()
        Write-Log 'splash shown'

        # fade in
        $steps = 30
        for ($i = 1; $i -le $steps; $i++) {
            $splash.Opacity = $i / [double]$steps
            [Windows.Forms.Application]::DoEvents()
            Start-Sleep -Milliseconds 14
        }

        # hold it long enough to read, keeping the window painted
        $until = (Get-Date).AddMilliseconds($HoldMs)
        while ((Get-Date) -lt $until) {
            [Windows.Forms.Application]::DoEvents()
            Start-Sleep -Milliseconds 15
        }

        return $splash
    }
    catch {
        # A cosmetic splash must never stop the app from opening.
        try { Write-Log "splash skipped - $($_.Exception.Message)" 'WARN' } catch { }
        Close-Splash
        return $null
    }
}

# Tears the splash down, image and stream included.
function Close-Splash {
    try { if ($script:Splash) { $script:Splash.Close(); $script:Splash.Dispose() } } catch { }
    $script:Splash = $null
    try { if ($script:SplashImg)    { $script:SplashImg.Dispose() } } catch { }
    $script:SplashImg = $null
    try { if ($script:SplashStream) { $script:SplashStream.Dispose() } } catch { }
    $script:SplashStream = $null
    try { Write-Log 'splash closed' } catch { }
}

# ------------------------------------------------------------------- UI -----
# The window is drawn from a small kit instead of stock WinForms chrome: the
# stock buttons, borders and scrollbars are light-themed and fight the dark
# canvas. Everything here is flat and rounded, in the colours taken from the
# logo - deep navy, electric blue, cyan - so the app and the splash read as one
# product instead of a form with a logo stuck on it.
$script:Ui = @{
    Bg       = [Drawing.Color]::FromArgb(11, 16, 32)
    Panel    = [Drawing.Color]::FromArgb(17, 26, 46)
    Inset    = [Drawing.Color]::FromArgb(12, 21, 38)
    Well     = [Drawing.Color]::FromArgb(10, 18, 33)
    Rail     = [Drawing.Color]::FromArgb(22, 32, 58)
    Border   = [Drawing.Color]::FromArgb(30, 43, 71)
    InnerBrd = [Drawing.Color]::FromArgb(25, 37, 62)
    Text     = [Drawing.Color]::FromArgb(233, 238, 249)
    Body     = [Drawing.Color]::FromArgb(190, 202, 226)
    Muted    = [Drawing.Color]::FromArgb(138, 153, 188)
    Faint    = [Drawing.Color]::FromArgb(98, 114, 145)
    Label    = [Drawing.Color]::FromArgb(108, 124, 161)
    Accent   = [Drawing.Color]::FromArgb(47, 123, 255)
    Accent2  = [Drawing.Color]::FromArgb(31, 182, 255)
    AccentHi = [Drawing.Color]::FromArgb(214, 230, 255)
    Danger   = [Drawing.Color]::FromArgb(255, 123, 133)
}

function Get-RoundPath {
    param([Drawing.RectangleF]$Rect, [float]$Radius)
    $path = New-Object Drawing.Drawing2D.GraphicsPath
    $rad = [Math]::Min($Radius, [Math]::Min($Rect.Width, $Rect.Height) / 2)
    if ($rad -le 0.5) { $path.AddRectangle($Rect); return $path }
    $d = $rad * 2
    $path.AddArc($Rect.X, $Rect.Y, $d, $d, 180, 90)
    $path.AddArc($Rect.Right - $d, $Rect.Y, $d, $d, 270, 90)
    $path.AddArc($Rect.Right - $d, $Rect.Bottom - $d, $d, $d, 0, 90)
    $path.AddArc($Rect.X, $Rect.Bottom - $d, $d, $d, 90, 90)
    $path.CloseFigure()
    return $path
}

# WinForms panels flicker badly when they paint their own background, and the
# property that fixes it is protected - so flip it behind the scenes.
function Set-DoubleBuffered {
    param([Windows.Forms.Control]$Control)
    try {
        $prop = $Control.GetType().GetProperty('DoubleBuffered', [Reflection.BindingFlags]'Instance, NonPublic')
        if ($prop) { $prop.SetValue($Control, $true, $null) }
    } catch { }
}

# A rounded surface: card, inset well, status strip. Backgrounds are given the
# colour of whatever sits *behind* the surface, so the corner pixels blend in.
function New-Surface {
    param(
        [Windows.Forms.Control]$Parent,
        [int]$X, [int]$Y, [int]$W, [int]$H,
        [Drawing.Color]$Fill,
        [Drawing.Color]$Border = [Drawing.Color]::Empty,
        [Drawing.Color]$Behind = $script:Ui.Bg,
        [int]$Radius = 12
    )
    $surface = New-Object Windows.Forms.Panel
    $surface.Bounds = New-Object Drawing.Rectangle -ArgumentList $X, $Y, $W, $H
    $surface.BackColor = $Behind
    [void](Set-DoubleBuffered $surface)
    # Event handlers do not keep the function's variables alive, so the look is
    # parked on the control itself and read back from the sender.
    $surface.Tag = @{ fill = $Fill; border = $Border; radius = $Radius }

    $surface.Add_Paint({
        param($s, $e)
        $look = $s.Tag
        $g = $e.Graphics
        $g.SmoothingMode = 'AntiAlias'
        $rect = New-Object Drawing.RectangleF -ArgumentList 0.5, 0.5, ($s.Width - 1), ($s.Height - 1)
        $path = Get-RoundPath -Rect $rect -Radius $look['radius']
        $fillBrush = New-Object Drawing.SolidBrush $look['fill']
        $g.FillPath($fillBrush, $path)
        $fillBrush.Dispose()
        if ($look['border'].A -gt 0) {
            $pen = New-Object Drawing.Pen $look['border'], 1
            $g.DrawPath($pen, $path)
            $pen.Dispose()
        }
        $path.Dispose()
    })

    $Parent.Controls.Add($surface)
    return $surface
}

# Flat button. It is a Panel rather than a Button because a real Button draws
# its own light-themed frame over anything painted on it; the Click events and
# the Enabled state behave the same, which is all the rest of the script uses.
function New-FlatButton {
    param(
        [Windows.Forms.Control]$Parent,
        [int]$X, [int]$Y, [int]$W, [int]$H,
        [string]$Text,
        [string]$Kind = 'ghost',        # primary | ghost | subtle | danger
        [Drawing.Color]$Behind = $script:Ui.Bg,
        [int]$Radius = 12,
        [float]$FontSize = 9.5,
        [switch]$Bold
    )
    $btn = New-Object Windows.Forms.Panel
    $btn.Bounds = New-Object Drawing.Rectangle -ArgumentList $X, $Y, $W, $H
    $btn.Text = $Text
    $btn.BackColor = $Behind
    $btn.Cursor = [Windows.Forms.Cursors]::Hand
    [void](Set-DoubleBuffered $btn)

    $fontStyle = if ($Bold) { [Drawing.FontStyle]::Bold } else { [Drawing.FontStyle]::Regular }
    $font = New-Object Drawing.Font 'Segoe UI', $FontSize, $fontStyle
    $flags = [Windows.Forms.TextFormatFlags]::HorizontalCenter -bor `
             [Windows.Forms.TextFormatFlags]::VerticalCenter -bor `
             [Windows.Forms.TextFormatFlags]::NoPrefix -bor `
             [Windows.Forms.TextFormatFlags]::EndEllipsis

    # Everything the painter needs lives on the control: handlers run after this
    # function has returned, when its local variables no longer exist.
    $btn.Tag = @{
        hover  = $false
        down   = $false
        kind   = $Kind
        radius = $Radius
        font   = $font
        flags  = $flags
    }

    $btn.Add_Paint({
        param($s, $e)
        $look = $s.Tag
        $kind = $look['kind']
        $radius = $look['radius']
        $font = $look['font']
        $flags = $look['flags']
        $g = $e.Graphics
        $g.SmoothingMode = 'AntiAlias'
        $hot  = [bool]$look['hover']
        $down = [bool]$look['down']
        $rect = New-Object Drawing.RectangleF -ArgumentList 0.5, 0.5, ($s.Width - 1), ($s.Height - 1)
        $path = Get-RoundPath -Rect $rect -Radius $radius

        if (-not $s.Enabled) {
            $fill = [Drawing.Color]::FromArgb(15, 23, 41)
            $edge = [Drawing.Color]::FromArgb(26, 37, 58)
            $ink  = [Drawing.Color]::FromArgb(78, 92, 120)
            $brush = New-Object Drawing.SolidBrush $fill
            $g.FillPath($brush, $path)
            $brush.Dispose()
            if ($edge.A -gt 0) { $pen = New-Object Drawing.Pen $edge, 1; $g.DrawPath($pen, $path); $pen.Dispose() }
        }
        elseif ($kind -eq 'primary') {
            $top = if ($down) { [Drawing.Color]::FromArgb(22, 78, 210) } elseif ($hot) { [Drawing.Color]::FromArgb(84, 146, 255) } else { [Drawing.Color]::FromArgb(62, 128, 255) }
            $bot = if ($down) { [Drawing.Color]::FromArgb(18, 64, 180) } elseif ($hot) { [Drawing.Color]::FromArgb(32, 96, 240) } else { [Drawing.Color]::FromArgb(24, 84, 226) }
            $brush = New-Object Drawing.Drawing2D.LinearGradientBrush $rect, $top, $bot, ([Drawing.Drawing2D.LinearGradientMode]::Vertical)
            $g.FillPath($brush, $path)
            $brush.Dispose()
            $pen = New-Object Drawing.Pen ([Drawing.Color]::FromArgb(96, 150, 255)), 1
            $g.DrawPath($pen, $path)
            $pen.Dispose()
            $ink = [Drawing.Color]::White
        }
        else {
            if ($kind -eq 'danger') {
                $fill = if ($down) { [Drawing.Color]::FromArgb(34, 20, 30) } elseif ($hot) { [Drawing.Color]::FromArgb(38, 23, 33) } else { [Drawing.Color]::FromArgb(26, 18, 28) }
                $edge = if ($hot) { [Drawing.Color]::FromArgb(96, 45, 58) } else { [Drawing.Color]::FromArgb(74, 35, 45) }
                $ink  = $script:Ui.Danger
            }
            elseif ($kind -eq 'subtle') {
                $fill = if ($down) { [Drawing.Color]::FromArgb(24, 38, 64) } elseif ($hot) { [Drawing.Color]::FromArgb(35, 55, 94) } else { [Drawing.Color]::FromArgb(27, 43, 74) }
                $edge = if ($hot) { [Drawing.Color]::FromArgb(58, 88, 140) } else { [Drawing.Color]::FromArgb(42, 62, 100) }
                $ink  = $script:Ui.AccentHi
            }
            else {
                $fill = if ($down) { [Drawing.Color]::FromArgb(13, 21, 37) } elseif ($hot) { [Drawing.Color]::FromArgb(24, 36, 61) } else { [Drawing.Color]::FromArgb(18, 28, 49) }
                $edge = if ($hot) { [Drawing.Color]::FromArgb(46, 66, 102) } else { $script:Ui.Border }
                $ink  = [Drawing.Color]::FromArgb(203, 214, 236)
            }
            $brush = New-Object Drawing.SolidBrush $fill
            $g.FillPath($brush, $path)
            $brush.Dispose()
            $pen = New-Object Drawing.Pen $edge, 1
            $g.DrawPath($pen, $path)
            $pen.Dispose()
        }

        $box = New-Object Drawing.Rectangle -ArgumentList 0, $(if ($down) { 1 } else { 0 }), $s.Width, $s.Height
        [Windows.Forms.TextRenderer]::DrawText($g, $s.Text, $font, $box, $ink, $flags)
        $path.Dispose()
    })

    $btn.Add_MouseEnter({ param($s, $e) $s.Tag['hover'] = $true; $s.Invalidate() })
    $btn.Add_MouseLeave({ param($s, $e) $s.Tag['hover'] = $false; $s.Tag['down'] = $false; $s.Invalidate() })
    $btn.Add_MouseDown({
        param($s, $e)
        if ($e.Button -eq [Windows.Forms.MouseButtons]::Left) { $s.Tag['down'] = $true; $s.Invalidate() }
    })
    $btn.Add_MouseUp({ param($s, $e) $s.Tag['down'] = $false; $s.Invalidate() })
    $btn.Add_EnabledChanged({ param($s, $e) $s.Invalidate() })

    $Parent.Controls.Add($btn)
    return $btn
}

# One half of a segmented switch. It is only a view: the hidden RadioButton it
# is tied to stays the source of truth, so Save-Config and everything else that
# reads $rbAllow.Checked keeps working untouched.
function New-Choice {
    param(
        [Windows.Forms.Control]$Parent,
        [int]$X, [int]$Y, [int]$W, [int]$H,
        [string]$Text,
        [Windows.Forms.RadioButton]$Radio,
        [Drawing.Color]$Behind,
        [int]$Radius = 8
    )
    $choice = New-Object Windows.Forms.Panel
    $choice.Bounds = New-Object Drawing.Rectangle -ArgumentList $X, $Y, $W, $H
    $choice.Text = $Text
    $choice.BackColor = $Behind
    $choice.Cursor = [Windows.Forms.Cursors]::Hand
    [void](Set-DoubleBuffered $choice)

    $plain = New-Object Drawing.Font 'Segoe UI', 9.5
    $heavy = New-Object Drawing.Font 'Segoe UI', 9.5, ([Drawing.FontStyle]::Bold)
    $flags = [Windows.Forms.TextFormatFlags]::HorizontalCenter -bor `
             [Windows.Forms.TextFormatFlags]::VerticalCenter -bor `
             [Windows.Forms.TextFormatFlags]::NoPrefix
    $choice.Tag = @{ hover = $false; radio = $Radio; plain = $plain; heavy = $heavy; flags = $flags; radius = $Radius }

    $choice.Add_Paint({
        param($s, $e)
        $look = $s.Tag
        $g = $e.Graphics
        $g.SmoothingMode = 'AntiAlias'
        $rect = New-Object Drawing.RectangleF -ArgumentList 1, 1, ($s.Width - 2), ($s.Height - 2)
        if ($look['radio'].Checked) {
            $path = Get-RoundPath -Rect $rect -Radius $look['radius']
            $brush = New-Object Drawing.SolidBrush ([Drawing.Color]::FromArgb(26, 45, 82))
            $g.FillPath($brush, $path)
            $brush.Dispose()
            $pen = New-Object Drawing.Pen ([Drawing.Color]::FromArgb(45, 84, 150)), 1
            $g.DrawPath($pen, $path)
            $pen.Dispose()
            $path.Dispose()
            $ink = $script:Ui.AccentHi
            $font = $look['heavy']
        }
        elseif ($look['hover']) {
            $path = Get-RoundPath -Rect $rect -Radius $look['radius']
            $brush = New-Object Drawing.SolidBrush ([Drawing.Color]::FromArgb(18, 29, 50))
            $g.FillPath($brush, $path)
            $brush.Dispose()
            $path.Dispose()
            $ink = [Drawing.Color]::FromArgb(170, 186, 214)
            $font = $look['plain']
        }
        else {
            $ink = $script:Ui.Muted
            $font = $look['plain']
        }

        $box = New-Object Drawing.Rectangle -ArgumentList 0, 0, $s.Width, $s.Height
        [Windows.Forms.TextRenderer]::DrawText($g, $s.Text, $font, $box, $ink, $look['flags'])
    })

    $choice.Add_MouseEnter({ param($s, $e) $s.Tag['hover'] = $true; $s.Invalidate() })
    $choice.Add_MouseLeave({ param($s, $e) $s.Tag['hover'] = $false; $s.Invalidate() })
    $choice.Add_Click({ param($s, $e) if (-not $s.Tag['radio'].Checked) { $s.Tag['radio'].Checked = $true } })

    $Parent.Controls.Add($choice)
    return $choice
}

